UPDATE public.seo_meta s SET title_tr='3D Baskı, 3D Tarama ve 3D Modelleme | 3dyanımda',description_tr='3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim.' FROM public.tenants t WHERE s.tenant_id=t.id AND t.slug='3dyanimda' AND s.path='/' AND s.title_tr='Prototip & kurumsal üretim | 3dyanımda' AND s.description_tr='İstanbul’da kurumsal 3D baskı, ürün geliştirme prototipleri, montaj yardımcıları ve küçük seri üretim. Teknik dosyanız için proje bazlı teklif.';
UPDATE public.site_settings s SET value='{"eyebrow_tr":"KURUMSAL 3D ÜRETİM ÇÖZÜMLERİ","title_tr":"Fikrinizden parçaya.\nÜretim yanınızda.","lead_tr":"Prototipten özel parçaya; 3D baskı, 3D tarama ve 3D modelleme hizmetleri. Dosyanızla, numunenizle veya henüz çizilmemiş fikrinizle başlayın.","cta_primary_tr":"Hemen teklif al","cta_secondary_tr":"Hizmetleri keşfet"}'::jsonb FROM public.tenants t WHERE s.tenant_id=t.id AND t.slug='3dyanimda' AND s.key='hero_content' AND s.value='{"eyebrow_tr":"KURUMSAL 3D ÜRETİM ÇÖZÜMLERİ","title_tr":"Tasarımınızdan\nüretiminizin\nbir parçasına.","lead_tr":"Ar-Ge, ürün geliştirme ve üretim ekipleri için 3D modelleme, fonksiyonel prototip ve küçük seri parça üretimi. Teknik ihtiyacınızı, uygulanabilir bir üretim planına dönüştürelim.","cta_primary_tr":"Teknik teklif alın","cta_secondary_tr":"Çözümleri inceleyin"}'::jsonb;
UPDATE public.seo_meta s SET title_tr='3D Baskı, 3D Tarama ve 3D Modelleme | 3dsanayi',description_tr='3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim.' FROM public.tenants t WHERE s.tenant_id=t.id AND t.slug='3dsanayi' AND s.path='/' AND s.title_tr='Endüstriyel parça & fikstür | 3dsanayi' AND s.description_tr='İstanbul’da sanayi için 3D baskı, fikstür, montaj aparatı, cihaz muhafazası ve fonksiyonel prototip üretimi. Kurumsal teknik teklif talebi.';
UPDATE public.site_settings s SET value='{"eyebrow_tr":"ÜRETİM EKİPLERİ İÇİN EKLEMELİ İMALAT","title_tr":"Üretiminize özel.\nİşinize hazır.","lead_tr":"Fikstür, aparat ve fonksiyonel parça ihtiyaçlarınız için 3D baskı, 3D tarama ve 3D modelleme. Teknik ihtiyacı birlikte tanımlayalım.","cta_primary_tr":"Hemen teklif al","cta_secondary_tr":"Hizmetleri keşfet"}'::jsonb FROM public.tenants t WHERE s.tenant_id=t.id AND t.slug='3dsanayi' AND s.key='hero_content' AND s.value='{"eyebrow_tr":"ÜRETİM EKİPLERİ İÇİN EKLEMELİ İMALAT","title_tr":"Üretim hattınıza\nözel düşünülmüş\nparçalar.","lead_tr":"Fikstür, konumlandırma aparatı, test parçası ve cihaz muhafazası ihtiyaçlarınız için proje bazlı 3D üretim. Sahadaki gereksinimden numune değerlendirmesine kadar teknik bir süreç.","cta_primary_tr":"Teknik teklif alın","cta_secondary_tr":"Çözümleri inceleyin"}'::jsonb;
