UPDATE public.site_settings s SET value='{"eyebrow_tr":"MİMARLIK & GAYRİMENKUL SUNUM ÇÖZÜMLERİ","title_tr":"Projenizi görün.\nDetayına dokunun.","lead_tr":"Mimari maket ve ölçekli sunum modelleri için 3D baskı, 3D tarama ve 3D modelleme. Projenizin ölçeğine ve sunum amacına uygun üretim.","cta_primary_tr":"Hemen teklif al","cta_secondary_tr":"Hizmetleri keşfet"}'::jsonb FROM public.tenants t WHERE s.tenant_id=t.id AND t.slug='maketyanimda' AND s.key='hero_content' AND s.value='{"eyebrow_tr":"MİMARLIK & GAYRİMENKUL SUNUM ÇÖZÜMLERİ","title_tr":"Projenizin\nölçeği değişir.\nEtkisi büyür.","lead_tr":"Mimarlık ofisleri, gayrimenkul geliştiricileri ve proje ekipleri için ölçekli fiziksel modeller. Tasarım kararından yatırımcı sunumuna, detay seviyesi amaca göre belirlenir.","cta_primary_tr":"Teknik teklif alın","cta_secondary_tr":"Çözümleri inceleyin"}'::jsonb;
