UPDATE public.site_settings s SET value='{"eyebrow_tr":"ÖZEL PLASTİK PARÇA & OTOMOTİV ÇÖZÜMLERİ","title_tr":"Aradığınız parça.\nYeni bir başlangıç.","lead_tr":"Bulunamayan plastik parçalar için 3D tarama, 3D modelleme ve 3D baskı. Örnek parçadan veya ölçüden başlayarak üretim yolunu belirleyelim.","cta_primary_tr":"Hemen teklif al","cta_secondary_tr":"Hizmetleri keşfet"}'::jsonb FROM public.tenants t WHERE s.tenant_id=t.id AND t.slug='parcayanimda' AND s.key='hero_content' AND s.value='{"eyebrow_tr":"ÖZEL PLASTİK PARÇA & OTOMOTİV ÇÖZÜMLERİ","title_tr":"Bulunamayan\nparçaya, yeni\nbir üretim yolu.","lead_tr":"Servisler, restorasyon atölyeleri ve teknik ekipler için özel plastik parça tasarımı. Örnek parçadan, ölçüden veya CAD dosyasından başlayarak üretim uygunluğunu değerlendirelim.","cta_primary_tr":"Teknik teklif alın","cta_secondary_tr":"Çözümleri inceleyin"}'::jsonb;
