INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/malzemeler/pla','PLA','Form ve sunum prototipleri 3dsanayi ile endüstriyel parça & fikstür için proje bazlı değerlendirme.','[{"title":"Endüstriyel parça & fikstür için değerlendirme","body":"Üretim ve bakım ekiplerinin kullanım senaryosuna özel parçalar. Geometri, yük, ortam koşulları ve montaj ilişkisi değerlendirilerek üretim kapsamı netleştirilir."},{"title":"Kullanım yaklaşımı","body":"Boyutsal görünüm ve form denemeleri için değerlendirilebilir. Sıcaklık, güneş ve yük altında kullanım ayrıca incelenmelidir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}]'::jsonb,'material','','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
