INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/3d-baski','3D Baskı','Dijital modelinizi fiziksel parçaya dönüştürün. parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Hangi ihtiyaçlar için?","body":"Form kontrolü, montaj denemesi, özel aparat ve düşük adetli parça ihtiyaçlarında 3D baskı değerlendirilebilir. Üretim kararı; parçanın görevi, yükleri, sıcaklığı, yüzey beklentisi ve adet bilgisiyle birlikte verilir."},{"title":"Teklif için ne göndermelisiniz?","body":"STL dosyanızı Studio’da açıp ölçüleri inceleyebilirsiniz. STEP, IGES, OBJ ve 3MF dosyalarını da teknik değerlendirme için iletebilirsiniz. Adedi, kritik ölçüleri, eşleşen parçaları ve hedef teslim tarihini talebe ekleyin."},{"title":"Malzeme ve üretim kararı","body":"PLA, PETG, ABS, ASA ve TPU farklı ihtiyaçlara cevap verir. Her malzemenin her geometriye uygun olduğu varsayılmaz. Yüzey, baskı yönü, doluluk ve destek ihtiyacı teknik değerlendirmede birlikte ele alınır."},{"title":"Numune ve tekrar üretim","body":"Montaj ilişkisi bulunan işlerde önce numune üzerinden ilerlemek yararlıdır. Onaylanan revizyon, malzeme ve adet bilgisi tekrar siparişte referans alınır. Tasarım değişiklikleri yeni revizyon olarak değerlendirilir."}]'::jsonb,'service','/cms/service-printing.jpg','[{"q":"STL olmadan teklif alabilir miyim?","a":"Evet. Fotoğraf, ölçü veya numune üzerinden modelleme ihtiyacıyla başlayabilirsiniz."},{"q":"Studio’daki fiyat kesin mi?","a":"Hesaplanan tutar ön tahmindir. Modelin üretilebilirliği, destekler, son işlemler ve teslimat teknik incelemede netleşir."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/3d-tarama','3D Tarama','Elinizdeki parçadan dijital modele geçin. parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Numuneden başlayan projeler","body":"Çizimi bulunmayan bir parça için ilk adım; boyut, yüzey, erişilebilirlik ve beklenen çıktı bilgisidir. Parçanın fotoğrafları üzerinden taramaya uygunluğu ve nasıl teslim alınacağı değerlendirilir."},{"title":"Tarama ile CAD aynı şey değildir","body":"Tarama yüzey geometrisini ölçüm verisine dönüştürür. Düzenlenebilir mühendislik modeli gerekiyorsa tersine mühendislik ve CAD modelleme ayrıca kapsamlandırılır. Teklifte beklenen dosya türü açıkça belirtilmelidir."},{"title":"Ölçüm planını birlikte belirleyelim","body":"Parlak, şeffaf, çok koyu veya iç yüzeyleri kapalı parçalar ek hazırlık gerektirebilir. Kritik delik, yatak ve bağlantı ölçülerini belirtin. Ulaşılabilir hassasiyet ve yöntem numunenin özelliklerine göre teyit edilir."},{"title":"Teslim edilecek veriler","body":"Projenin amacına göre işlenmiş yüzey ağı veya modelleme aşamasına girdi hazırlanır. Bir parçanın yeniden üretimi isteniyorsa tarama, CAD düzenlemesi ve 3D baskı tek talepte değerlendirilebilir."}]'::jsonb,'service','/cms/service-scanning.jpg','[{"q":"Parçayı göndermem gerekiyor mu?","a":"Fotoğraf ve yaklaşık ölçülerle ön değerlendirme başlar. Numunenin teslimi veya ölçüm yöntemi proje özelinde kararlaştırılır."},{"q":"Kırık parça taranabilir mi?","a":"Eksik alanlar ve simetriler incelenir. Eksik geometrinin yeniden tasarlanması gerekiyorsa ayrıca modelleme kapsamı belirlenir."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/3d-modelleme','3D Modelleme','Fikri, ölçüyü veya numuneyi üretime hazırlayın. parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Doğru model, açık bir ihtiyaçla başlar","body":"Eskiz, teknik resim, numune veya tarama verisi başlangıç olabilir. Parçanın nerede kullanılacağını, bağlanacağı bileşenleri ve korunması gereken ölçüleri belirterek tasarım kapsamını netleştirin."},{"title":"Üretime uygun tasarım","body":"Duvar kalınlığı, bağlantı bölgeleri, montaj payları ve baskı yönü üretim yöntemiyle birlikte düşünülür. Görsel model ile işlevsel parça tasarımı farklı teslim beklentilerine sahiptir."},{"title":"Revizyon ve dosya teslimi","body":"Modelleme teklifinde teslim formatı, revizyon kapsamı ve onay adımları tanımlanır. Düzenlenebilir CAD, STEP veya baskıya uygun STL beklentinizi başlangıçta belirtin; tüm formatlar her model türünde aynı işlevi sunmaz."},{"title":"Fiziksel doğrulama","body":"Gerekli projelerde ilk modelin 3D baskısıyla form ve montaj değerlendirilir. Numuneden gelen geri bildirim tasarım revizyonuna aktarılır. Seri adede geçiş onaylanan model üzerinden planlanır."}]'::jsonb,'service','/cms/service-modeling.jpg','[{"q":"Sadece fotoğraftan model yapılır mı?","a":"Fotoğraf formu anlatabilir; işlevsel uyum için ölçü, ölçek veya numune gerekir. Tek fotoğraf hassas ölçü doğrulamasının yerine geçmez."},{"q":"Sadece modelleme hizmeti alabilir miyim?","a":"Evet. Baskı zorunlu değildir; teslim formatı ve kullanım amacı teklif kapsamında belirlenir."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/cozumler/ic-trim-kapaklar','İç trim & kapaklar','Araç içi estetik ve işlevsel plastik parçaların örnek veya ölçü üzerinden değerlendirilmesi.','[{"title":"Projenizin başlangıcı","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}]'::jsonb,'solution','/brand/industrial/parts.webp','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/cozumler/ozel-adaptorler','Özel adaptörler','Mevcut iki bileşen arasındaki geometrik uyum için projeye özel plastik adaptörler.','[{"title":"Projenizin başlangıcı","body":"Yeni bir gövde, bağlantı veya adaptör fikrini montaj ilişkilerini test edebileceğiniz fiziksel modele dönüştürün."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}]'::jsonb,'solution','/brand/industrial/parts.webp','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/cozumler/baglanti-sabitleme','Bağlantı & sabitleme','Güvenlik kritik olmayan uygulamalar için plastik tutucular, yönlendiriciler ve bağlantı parçaları.','[{"title":"Projenizin başlangıcı","body":"Eskiyen veya katalogda bulunmayan yardımcı plastik parçalar için üretim alternatiflerini ele alıyoruz."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}]'::jsonb,'solution','/brand/industrial/parts.webp','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/cozumler/ornekten-parca-modelleme','Örnekten parça modelleme','Mevcut parça, eskiz veya ölçü setinden yeni üretime yönelik dijital model geliştirme.','[{"title":"Projenizin başlangıcı","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}]'::jsonb,'solution','/brand/industrial/parts.webp','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/malzemeler/pla','PLA','Form ve sunum prototipleri parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.','[{"title":"Özel plastik parça & otomotiv için değerlendirme","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Kullanım yaklaşımı","body":"Boyutsal görünüm ve form denemeleri için değerlendirilebilir. Sıcaklık, güneş ve yük altında kullanım ayrıca incelenmelidir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}]'::jsonb,'material','','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
