INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/malzemeler/tpu','TPU','Esnek parça ve temas yüzeyleri parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.','[{"title":"Özel plastik parça & otomotiv için değerlendirme","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Kullanım yaklaşımı","body":"Esneklik gerektiren koruyucu, tampon ve kavrama parçalarında değerlendirilebilir. Sertlik derecesi, et kalınlığı ve bağlantı biçimi birlikte seçilir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}]'::jsonb,'material','','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/malzemeler/muhendislik-polimerleri','Mühendislik polimerleri','Özel çalışma koşulları parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.','[{"title":"Özel plastik parça & otomotiv için değerlendirme","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Kullanım yaklaşımı","body":"Naylon ve katkılı polimerler için malzeme tedariki, kurutma, cihaz uyumu ve kullanım gereksinimleri proje bazında teyit edilir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}]'::jsonb,'material','','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/teklif-icin-dosya-hazirlama','Teklif için dosyanızı nasıl hazırlarsınız?','Teklif talebinde model kadar kullanım bilgisi de önemlidir. parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.','[{"title":"Özel plastik parça & otomotiv projelerinde","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"Dosyanın birimini belirtin","body":"STL dosyası birim bilgisi taşımaz. Modelinizi milimetre olarak dışa aktarın ve Studio’da görünen boyutları kontrol edin. STEP dosyanız varsa montaj ilişkilerini değerlendirmek için ayrıca paylaşabilirsiniz."},{"title":"Teknik ihtiyacı tarif edin","body":"Adet, renk, yük, sıcaklık, eşleşen parçalar ve kritik ölçüleri yazın. Tüm ölçülerin eşit derecede kritik olduğunu varsaymak teklifin kapsamını belirsizleştirir."},{"title":"Sürümü takip edin","body":"Dosya adına parça kodu ve revizyon ekleyin. Birden fazla parçanın set halinde üretilmesini istiyorsanız her parça için adet belirtin."}]'::jsonb,'guide','','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/3d-baski-fiyatlandirma','3D baskı fiyatı nasıl belirlenir?','Malzeme, üretim süresi ve teknik ihtiyaçlar birlikte değerlendirilir.','[{"title":"Özel plastik parça & otomotiv projelerinde","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"Hacim ve malzeme","body":"Aynı dış boyuttaki iki model farklı hacim ve duvar yapısına sahip olabilir. Malzeme tüketimi, destekler ve fire üretim hazırlığında değerlendirilir."},{"title":"Adet ve işlem süresi","body":"Tekrarlanan parçaların planlaması, kurulum ve son işlem toplam maliyeti etkiler. Büyük bir parçanın üretimi ile küçük parçaların toplu üretimi aynı değerlendirme değildir."},{"title":"Ön tahmin ve kesin teklif","body":"Studio hesabı bir bütçe göstergesidir. Dilimleme, üretilebilirlik, montaj gereksinimi ve teslimat kontrolü sonrası resmi teklif netleşir."}]'::jsonb,'guide','','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/tarama-ve-tersine-muhendislik','3D tarama mı, tersine mühendislik mi?','Ölçülen yüzey ile yeniden tasarlanmış CAD modelinin farkı. parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.','[{"title":"Özel plastik parça & otomotiv projelerinde","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"Yüzey verisi","body":"Tarama dış yüzeyin ölçümünü sağlar. Delikler, iç kanallar ve erişilemeyen alanlar için ek ölçüm gerekebilir."},{"title":"Düzenlenebilir model","body":"CAD modelleme, işlevi tanımlanan yüzeyler ve ölçüler üzerinden yeni bir dijital tasarım oluşturur. Geometriyi düzenlemek ve üretim için değiştirmek bu aşamada mümkündür."},{"title":"Doğru teslim tanımı","body":"Sadece görselleştirme, arşivleme veya yeniden üretim farklı çıktılar gerektirir. Hangi amaçla kullanılacağını teklif öncesinde belirtin."}]'::jsonb,'guide','','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/numune-ve-revizyon','Numuneden tekrar siparişe','Parçayı onaylamak ve doğru revizyonla devam etmek. parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.','[{"title":"Özel plastik parça & otomotiv projelerinde","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"İlk kontrol","body":"Numuneyi gerçek montaj ortamında değerlendirin. Uyum, erişim ve kullanım sırasında karşılaşılan noktaları fotoğraf ve ölçüyle kaydedin."},{"title":"Revizyon kararı","body":"Değişen ölçüleri açıkça belirtin. Tasarım güncellemelerinin eski dosyayla karışmaması için yeni bir revizyon adı kullanın."},{"title":"Tekrar üretim","body":"Onaylanan dosya, malzeme ve üretim ayarları tekrar talebin başlangıcıdır. Malzeme veya kullanım koşulu değiştiğinde yeniden değerlendirme gerekir."}]'::jsonb,'guide','','[]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/bolgeler/istanbul','İstanbul 3D üretim','İstanbul için özel plastik parça & otomotiv odağında 3D baskı, 3D tarama ve 3D modelleme talepleri.','[{"title":"Özel plastik parça & otomotiv","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Talebi doğru hazırlayın","body":"Adet, renk, yük, sıcaklık, eşleşen parçalar ve kritik ölçüleri yazın. Tüm ölçülerin eşit derecede kritik olduğunu varsaymak teklifin kapsamını belirsizleştirir."},{"title":"Üç hizmeti birlikte değerlendirin","body":"Üretime hazır dosyanız varsa 3D baskıyla başlayabilirsiniz. Fiziksel parçanın geometrisi gerekiyorsa tarama, ölçü veya eskizden yeni bir tasarım gerekiyorsa modelleme kapsamı belirlenir. Talebiniz tek bir hizmetle sınırlı olmak zorunda değildir."}]'::jsonb,'location','','[{"q":"İstanbul’un her ilçesinde şubeniz var mı?","a":"Hayır. Çalışma noktamız Ataşehir, Örnek Mahallesi’dir. İlçe seçimi talebinizin ve teslimat planının değerlendirilmesine yardımcı olur; ayrı şube anlamına gelmez."},{"q":"Ön değerlendirme için atölyeye gelmem gerekir mi?","a":"Dosya, fotoğraf ve ihtiyaç bilgisiyle uzaktan başlayabilirsiniz. Fiziksel numune veya görüşme gerektiğinde uygun yöntem birlikte belirlenir."}]'::jsonb,'published','istanbul','','','','İstanbul’da bulunamayan bir plastik parça için talep oluştururken önce fotoğrafları, yaklaşık ölçüleri ve parçanın görevini paylaşın. Numune değerlendirmesi için çalışma noktamız Ataşehir, Örnek Mahallesi’dir. Kırık parçanın yalnızca sağlam yüzünü değil, bağlantı ve montaj bölgelerini de göstermek yararlıdır. Eş parça veya karşılıklı bir yüz varsa bunun bilgisi eksik geometrinin yorumlanmasına yardımcı olur. Yeniden üretim kararı parçanın görevi ve çalışma koşulları incelendikten sonra verilir.','Orijinal numuneyi göndermeden önce hangi parçaların birlikte inceleneceğini belirleyelim. Eşleşen kapak veya bağlantı elemanı varsa fotoğrafını da talebe ekleyin. Numunenin gönderimi, iadesi ve yeni parçanın teslimi proje planında ayrı ayrı değerlendirilir.','İşletme sahibinin çalışma yeri beyanı: Örnek Mahallesi, Ataşehir / İstanbul. 2 Ekim 2026 proje görüşmesi.','2026-10-02T00:00:00Z' FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
